import React from "react";
import { useState } from "react";

function StateDemo() {
    const [videoName, setVideoName] = useState("fetching data");
    const [videoLikes, setVideoLikes] = useState(95)

    return (
        <>
            <h1> States Demo</h1>
            <h6> Video Name  : {videoName} </h6>
            <h6> Likes: {videoLikes} </h6>
            <button onClick={() => { setVideoLikes(videoLikes + 1) }}> Like Video </button>
            <button onClick={() => { setVideoLikes(videoLikes - 1) }}> DisLike Video </button>
            {
                videoLikes >= 100 &&
                <p> likes reached the 100 </p>
            }

        </>
    );
}

function ShowMessage() {
    const [isVisible, setIsVisible] = useState(true);

    return (
        <div>
            <button onClick={() => setIsVisible(!isVisible)}>
                {isVisible ? "Hide" : "Show"} Message
            </button>

            {isVisible && <p>This is a secret message!</p>}
        </div>
    );
}


export { StateDemo, ShowMessage };
